(()=>{'use strict';
const $=id=>document.getElementById(id),api=(window.MIYAR_CONFIG?.apiBase||location.origin).replace(/\/$/,''),state={available:false,busy:false,result:null,input:null,sequence:0};
const examples={civil:{text:'Ensure successful project delivery by assessing site and soil conditions, developing and reviewing designs and specs, overseeing materials and execution, and producing documentation to maintain quality, compliance, and informed decision-making.',field:'Engineering',seniority:'Professional',constraints:'Individual contributor; no management responsibilities.'},payroll:{text:'رفع دقة احتساب الرواتب والاستقطاعات ومراجعة مسيرات الأجور وتسوية فروقات الرواتب وإعداد تقارير شهرية لمدير المالية دون إدارة فريق.',field:'الموارد البشرية والرواتب',seniority:'Professional',constraints:'دور تخصصي فردي وليس مديرًا. يرفع تقاريره إلى مدير المالية.'},development:{text:'تحسين وضوح الأدوار وتحديث الأوصاف الوظيفية وتحليل التداخل بين المسؤوليات واقتراح مؤشرات أداء للأدوار بالتعاون مع مديري الإدارات.',field:'الموارد البشرية والتطوير التنظيمي',seniority:'Professional',constraints:'لا يدير فريقًا ولا يعتمد الهيكل أو الدرجات الوظيفية؛ يقدم توصيات للمراجعة.'}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function message(text,error=false){$('request-state').textContent=text;$('request-state').classList.toggle('error',error);}
function clearResult(){state.result=null;state.input=null;$('result').hidden=true;$('result').replaceChildren();$('empty-result').hidden=false;$('feedback-form').hidden=true;$('feedback-form').reset();message('');}
async function request(path,options={},timeout=90000){const r=await fetch(api+path,{...options,signal:AbortSignal.timeout(timeout),cache:'no-store'});let data;try{data=await r.json();}catch{throw Error('تعذّر قراءة استجابة الخدمة. أعد المحاولة بعد قليل.');}if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'تحقق من المدخلات ثم أعد المحاولة.');return data;}
async function connect(){state.available=false;$('review-fields').disabled=true;$('retry-status').hidden=true;$('service-state').textContent='جارٍ الاتصال بالخدمة…';$('service-dot').className='dot';try{const v=await request('/api/v1/review/strategic/status');state.available=!!(v.enabled&&v.configured&&v.remainingToday>0);$('service-dot').className='dot '+(state.available?'ready':'error');$('service-state').textContent=state.available?'المحرك جاهز للتجربة':!v.enabled?'التجربة غير متاحة حاليًا':!v.configured?'المحرك قيد الإعداد':'اكتمل حد التجربة لهذا اليوم';const until=v.expiresAt?new Date(v.expiresAt).toLocaleDateString('ar-SA',{timeZone:'Asia/Riyadh',calendar:'gregory',day:'numeric',month:'long'}):'';$('service-detail').textContent=state.available?'متاحة حتى '+until+' · '+v.dailyLimit+' محاولة يوميًا لجميع المشاركين.':!v.enabled?'تواصل مع منسق الاختبار لتفعيل فترة جديدة.':'أعد الاتصال لاحقًا.';$('review-fields').disabled=!state.available;$('retry-status').hidden=state.available;}catch(e){$('service-state').textContent='تعذّر الاتصال بالخدمة';$('service-detail').textContent='أعد الاتصال؛ قد يستغرق تشغيل الخادم بعد الخمول نحو دقيقة.';$('service-dot').className='dot error';$('retry-status').hidden=false;}}
function render(result){const matched=result.route==='matched-objective',blocked=result.status==='blocked';$('empty-result').hidden=true;$('result').hidden=false;const title=blocked?'لم يجتز المقترح فحص الملاءمة':result.finalTitle;const note=result.occupationCode?'المسمى والرمز مقترح مرتبط بالعينة المرجعية ويحتاجان مراجعة مهنية.':'لم يُسند رمز رسمي لهذا المقترح. راجع دليل المهن قبل اختيار الترميز؛ هذا لا يثبت أن المهنة جديدة.';$('result').innerHTML='<p class="result-label">'+(matched?'مطابقة هدف مرجعي · Embedding':'اقتراح مولّد · LLM')+'</p><h3 class="proposal-title" dir="auto">'+esc(title)+'</h3><div class="result-grid"><div class="metric"><span>رمز المهنة</span><strong>'+esc(result.occupationCode||'غير مسند')+'</strong></div><div class="metric"><span>التشابه الدلالي · ليس ثقة</span><strong dir="ltr">'+esc(Number(result.cosineSimilarity).toFixed(4))+'</strong></div></div><p class="result-note">'+esc(blocked?'منع المحرك اعتماد المسمى لعدم استيفاء القيود. راجع المدخلات وملاحظات التحقق.':note)+'</p><p class="rationale" dir="auto">'+esc(result.finalRationale)+'</p><details><summary>تفاصيل المطابقة والتحقق</summary><p>عتبة المطابقة: '+esc(result.threshold)+' · رمز التعليم: '+esc(result.educationCode||'غير مسند')+'</p><p>أقرب مسمى في العينة: '+esc(result.matchedCandidate)+'</p><p dir="auto">'+esc(result.validation?.rationale||'')+'</p><p dir="ltr">Embedding: '+esc(result.embeddingModel)+'<br>LLM: '+esc(result.generationModel)+'</p></details>';$('feedback-form').hidden=false;}
document.querySelectorAll('[data-example]').forEach(button=>button.addEventListener('click',()=>{clearResult();const e=examples[button.dataset.example];$('objective').value=e.text;$('domain').value=e.field;$('seniority').value=e.seniority;$('constraints').value=e.constraints;}));
$('review-form').addEventListener('input',()=>{if(!state.busy&&state.result)clearResult();});
$('review-form').addEventListener('reset',()=>{state.sequence++;clearResult();});
$('review-form').addEventListener('submit',async event=>{event.preventDefault();if(state.busy||!state.available||!event.currentTarget.reportValidity())return;const input={text:$('objective').value.trim(),field:$('domain').value.trim(),seniority:$('seniority').value,constraints:$('constraints').value.trim(),consentExternalProcessing:$('consent').checked};clearResult();state.busy=true;$('review-fields').disabled=true;const sequence=++state.sequence;message('جارٍ تحليل الهدف والتحقق من ملاءمة المسمى… قد يستغرق ذلك نحو دقيقة.');try{const result=await request('/api/v1/review/strategic',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)},300000);if(sequence!==state.sequence)return;state.result=result;state.input=input;render(result);message('اكتمل التحليل. راجع النتيجة وسجّل ملاحظاتك.');}catch(e){if(sequence===state.sequence)message(e.name==='TimeoutError'?'استغرق الطلب وقتًا أطول من المتوقع. أعد المحاولة بعد قليل.':e.message||'تعذّر التحليل.',true);}finally{state.busy=false;$('review-fields').disabled=!state.available;}});
$('feedback-form').addEventListener('submit',event=>{event.preventDefault();if(!state.result||!event.currentTarget.reportValidity())return;const report={product:'Miyar',version:'5.0.5',reviewedAt:new Date().toISOString(),scope:'expert-trial-proposal-not-approval',input:state.input,result:state.result,review:{assessment:$('assessment').value,expectedTitleOrCode:$('expected-title').value.trim(),comments:$('comments').value.trim()}};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Miyar-expert-review-'+Date.now()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('retry-status').addEventListener('click',connect);connect();
})();
